basePowerCallback(pokemon, target, move) {
      if (!pokemon.item) {
        this.debug("BP doubled for no item");
        return move.basePower * 2;
      }
      return move.basePower;
    }

onHit(target) {
      const stats = [];
      let stat;
      for (stat in target.boosts) {
        if (target.boosts[stat] < 6) {
          stats.push(stat);
        }
      }
      if (stats.length) {
        const randomStat = this.sample(stats);
        const boost = {};
        boost[randomStat] = 2;
        this.boost(boost);
      } else {
        return false;
      }
    }

onHit(target) {
      if (this.activePerHalf === 1) return false;
      const action = this.queue.willMove(target);
      if (action) {
        this.queue.prioritizeAction(action);
        this.add("-activate", target, "move: After You");
      } else {
        return false;
      }
    }

onHit(target, source, move) {
        if (target?.statsRaisedThisTurn) {
          target.addVolatile("confusion", source, move);
        }
      }

onHit(target, source, move) {
        if (target?.statsRaisedThisTurn) {
          target.addVolatile("confusion", source, move);
        }
      }

onRestart(pokemon) {
        const counter = this.effectState.counter || 1;
        this.debug(`Ally Switch success chance: ${Math.round(100 / counter)}%`);
        const success = this.randomChance(1, counter);
        if (!success) {
          delete pokemon.volatiles["allyswitch"];
          return false;
        }
        if (this.effectState.counter < this.effect.counterMax) {
          this.effectState.counter *= 3;
        }
        this.effectState.duration = 2;
      }

onStart() {
        this.effectState.counter = 3;
      }

onHit(pokemon) {
      let success = true;
      if (this.gameType !== "doubles" && this.gameType !== "triples") success = false;
      if (pokemon.side.active.length === 3 && pokemon.position === 1) success = false;
      const newPosition = pokemon.position === 0 ? pokemon.side.active.length - 1 : 0;
      if (!pokemon.side.active[newPosition]) success = false;
      if (pokemon.side.active[newPosition].fainted) success = false;
      if (!success) {
        this.add("-fail", pokemon, "move: Ally Switch");
        this.attrLastMove("[still]");
        return this.NOT_FAIL;
      }
      this.swapPosition(pokemon, newPosition, "[from] move: Ally Switch");
    }

onPrepareHit(pokemon) {
      return pokemon.addVolatile("allyswitch");
    }

onHit(target, source, move) {
        if (source.isActive) target.addVolatile("trapped", source, move, "trapper");
      }

onHit(target, source, move) {
        if (source.isActive) target.addVolatile("trapped", source, move, "trapper");
      }

onResidual(pokemon) {
        this.heal(pokemon.baseMaxhp / 16);
      }

onStart(pokemon) {
        this.add("-start", pokemon, "Aqua Ring");
      }

onHit(target, source, move) {
      this.add("-activate", source, "move: Aromatherapy");
      let success = false;
      const allies = [...target.side.pokemon, ...target.side.allySide?.pokemon || []];
      for (const ally of allies) {
        if (ally !== source && !this.suppressingAbility(ally)) {
          if (ally.hasAbility("sapsipper")) {
            this.add("-immune", ally, "[from] ability: Sap Sipper");
            continue;
          }
          if (ally.hasAbility("goodasgold")) {
            this.add("-immune", ally, "[from] ability: Good as Gold");
            continue;
          }
          if (ally.volatiles["substitute"] && !move.infiltrates) continue;
        }
        if (ally.cureStatus()) success = true;
      }
      return success;
    }

onHit(target) {
      const moves = [];
      for (const pokemon of target.side.pokemon) {
        if (pokemon === target) continue;
        for (const moveSlot of pokemon.moveSlots) {
          const moveid = moveSlot.id;
          const move = this.dex.moves.get(moveid);
          if (move.flags["noassist"] || move.isZ || move.isMax) {
            continue;
          }
          moves.push(moveid);
        }
      }
      let randomMove = "";
      if (moves.length) randomMove = this.sample(moves);
      if (!randomMove) {
        return false;
      }
      this.actions.useMove(randomMove, target);
    }

basePowerCallback(pokemon, target, move) {
      if (target.hurtThisTurn) {
        this.debug("BP doubled on damaged target");
        return move.basePower * 2;
      }
      return move.basePower;
    }

onBeforeMove(pokemon, target, move) {
        this.add("-activate", pokemon, "move: Attract", "[of] " + this.effectState.source);
        if (this.randomChance(1, 2)) {
          this.add("cant", pokemon, "Attract");
          return false;
        }
      }

onEnd(pokemon) {
        this.add("-end", pokemon, "Attract", "[silent]");
      }

onStart(pokemon, source, effect) {
        if (!(pokemon.gender === "M" && source.gender === "F") && !(pokemon.gender === "F" && source.gender === "M")) {
          this.debug("incompatible gender");
          return false;
        }
        if (!this.runEvent("Attract", pokemon, source)) {
          this.debug("Attract event failed");
          return false;
        }
        if (effect.name === "Cute Charm") {
          this.add("-start", pokemon, "Attract", "[from] ability: Cute Charm", `[of] ${source}`);
        } else if (effect.name === "Destiny Knot") {
          this.add("-start", pokemon, "Attract", "[from] item: Destiny Knot", `[of] ${source}`);
        } else {
          this.add("-start", pokemon, "Attract");
        }
      }

onUpdate(pokemon) {
        if (this.effectState.source && !this.effectState.source.isActive && pokemon.volatiles["attract"]) {
          this.debug(`Removing Attract volatile on ${pokemon}`);
          pokemon.removeVolatile("attract");
        }
      }

onTryImmunity(target, source) {
      return target.gender === "M" && source.gender === "F" || target.gender === "F" && source.gender === "M";
    }

onModifyType(move, pokemon) {
      if (pokemon.species.name === "Morpeko-Hangry") {
        move.type = "Dark";
      } else {
        move.type = "Electric";
      }
    }

onTry(source) {
      if (source.species.baseSpecies === "Morpeko") {
        return;
      }
      this.attrLastMove("[still]");
      this.add("-fail", source, "move: Aura Wheel");
      this.hint("Only a Pokemon whose form is Morpeko or Morpeko-Hangry can use this move.");
      return null;
    }

durationCallback(target, source, effect) {
        if (source?.hasItem("lightclay")) {
          return 8;
        }
        return 5;
      }

onAnyModifyDamage(damage, source, target, move) {
        if (target !== source && this.effectState.target.hasAlly(target)) {
          if (target.side.getSideCondition("reflect") && this.getCategory(move) === "Physical" || target.side.getSideCondition("lightscreen") && this.getCategory(move) === "Special") {
            return;
          }
          if (!target.getMoveHitData(move).crit && !move.infiltrates) {
            this.debug("Aurora Veil weaken");
            if (this.activePerHalf > 1) return this.chainModify([2732, 4096]);
            return this.chainModify(0.5);
          }
        }
      }

onSideEnd(side) {
        this.add("-sideend", side, "move: Aurora Veil");
      }

onSideStart(side) {
        this.add("-sidestart", side, "move: Aurora Veil");
      }

onTry() {
      return this.field.isWeather(["hail", "snowscape"]);
    }

